// Rural rice terraces at sunset — direct 2D painterly composite
// Canvas 1200 x 800

// ---------- helpers ----------
function makeNoise(seed) {
  let s = seed >>> 0;
  const perm = new Uint8Array(512);
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  let st = s || 1;
  for (let i = 255; i > 0; i--) {
    st = (st * 1664525 + 1013904223) >>> 0;
    const j = st % (i + 1);
    const t = p[i]; p[i] = p[j]; p[j] = t;
  }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  const fade = t => t * t * t * (t * (t * 6 - 15) + 10);
  const lerp = (a, b, t) => a + (b - a) * t;
  function grad2(h, x, y) {
    const g = h & 7;
    return ((g & 1) ? -x : x) + ((g & 2) ? -y : y);
  }
  function noise2(x, y) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const X = xi & 255, Y = yi & 255;
    const u = fade(xf), v = fade(yf);
    const a = perm[perm[X] + Y];
    const b = perm[perm[X + 1] + Y];
    const c = perm[perm[X] + Y + 1];
    const d = perm[perm[X + 1] + Y + 1];
    return lerp(
      lerp(grad2(a, xf, yf), grad2(b, xf - 1, yf), u),
      lerp(grad2(c, xf, yf - 1), grad2(d, xf - 1, yf - 1), u),
      v
    );
  }
  return noise2;
}

const noise = makeNoise(1337);

function fbm(x, y, oct, lac, gain) {
  let amp = 1, freq = 1, sum = 0, norm = 0;
  for (let i = 0; i < oct; i++) {
    sum += noise(x * freq, y * freq) * amp;
    norm += amp;
    amp *= gain; freq *= lac;
  }
  return sum / norm;
}

function rnd(a, b) { return a + (b - a) * Math.random(); }
function mix(c1, c2, t) {
  return [
    c1[0] + (c2[0] - c1[0]) * t,
    c1[1] + (c2[1] - c1[1]) * t,
    c1[2] + (c2[2] - c1[2]) * t
  ];
}
function col(c, a) {
  const r = c[0] | 0, g = c[1] | 0, b = c[2] | 0;
  return a === undefined ? `rgb(${r},${g},${b})` : `rgba(${r},${g},${b},${a})`;
}

// ---------- palette ----------
const peach = [252, 208, 168];
const cream = [255, 238, 214];
const coral = [248, 178, 142];
const softRose = [242, 176, 168];
const lavenderFar = [176, 158, 190];
const lavenderDeep = [132, 118, 158];
const hillMid = [122, 108, 138];
const hillNear = [96, 86, 112];
const waterAmber = [246, 190, 128];
const waterPeach = [244, 196, 160];
const waterPale = [230, 208, 194];
const waterOlive = [136, 150, 108];
const waterLav = [172, 162, 196];
const bankLit = [222, 176, 122];
const bankDark = [104, 76, 56];
const bankMid = [162, 124, 88];
const riceGreen = [116, 136, 76];
const riceDark = [70, 88, 50];

// ---------- sky ----------
function paintSky() {
  const g = ctx.createLinearGradient(0, 0, 0, H * 0.55);
  g.addColorStop(0, col([252, 196, 156]));
  g.addColorStop(0.28, col(peach));
  g.addColorStop(0.58, col(cream));
  g.addColorStop(0.85, col([248, 224, 196]));
  g.addColorStop(1, col([236, 208, 190]));
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H * 0.6);

  const gr = ctx.createRadialGradient(W * 0.72, H * 0.42, 30, W * 0.72, H * 0.42, W * 0.9);
  gr.addColorStop(0, col([255, 226, 178], 0.55));
  gr.addColorStop(0.5, col([252, 200, 170], 0.22));
  gr.addColorStop(1, col(peach, 0));
  ctx.fillStyle = gr;
  ctx.fillRect(0, 0, W, H * 0.6);

  // sun disc
  const sd = ctx.createRadialGradient(W * 0.72, H * 0.395, 4, W * 0.72, H * 0.395, 90);
  sd.addColorStop(0, col([255, 246, 218], 0.85));
  sd.addColorStop(0.35, col([255, 228, 174], 0.4));
  sd.addColorStop(1, col([252, 200, 170], 0));
  ctx.fillStyle = sd;
  ctx.fillRect(W * 0.55, H * 0.30, W * 0.35, H * 0.20);

  // cloud streaks — painterly, varied
  for (let i = 0; i < 32; i++) {
    const cy = rnd(H * 0.04, H * 0.36);
    const cx = rnd(-120, W + 120);
    const w = rnd(140, 520);
    const h = rnd(5, 22);
    const c = Math.random() < 0.5
      ? mix([248, 190, 168], [255, 228, 216], Math.random())
      : mix([236, 176, 176], [248, 206, 196], Math.random());
    ctx.fillStyle = col(c, rnd(0.09, 0.26));
    ctx.beginPath();
    ctx.ellipse(cx, cy, w, h, rnd(-0.05, 0.05), 0, Math.PI * 2);
    ctx.fill();
  }
  // thin bright cloud wisp highlight
  for (let i = 0; i < 6; i++) {
    const cy = rnd(H * 0.08, H * 0.30);
    const cx = rnd(0, W);
    const w = rnd(200, 400);
    ctx.fillStyle = col([255, 240, 216], rnd(0.10, 0.20));
    ctx.beginPath();
    ctx.ellipse(cx, cy, w, rnd(2, 5), 0, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ---------- distant hills ----------
function paintHills() {
  const baseY = H * 0.42;
  ctx.beginPath();
  ctx.moveTo(0, baseY + 30);
  for (let x = 0; x <= W; x += 12) {
    const n = fbm(x * 0.004 + 3, 0.5, 3, 2, 0.5);
    const y = baseY - 12 + n * 44 - Math.sin(x * 0.002 + 1) * 14;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H * 0.6);
  ctx.lineTo(0, H * 0.6);
  ctx.closePath();
  const g1 = ctx.createLinearGradient(0, baseY - 40, 0, H * 0.55);
  g1.addColorStop(0, col(mix(lavenderFar, peach, 0.35)));
  g1.addColorStop(1, col(mix(lavenderFar, hillMid, 0.6)));
  ctx.fillStyle = g1;
  ctx.fill();

  const baseY2 = H * 0.475;
  ctx.beginPath();
  ctx.moveTo(0, baseY2 + 40);
  for (let x = 0; x <= W; x += 10) {
    const n = fbm(x * 0.006 + 11, 1.7, 4, 2.1, 0.55);
    const y = baseY2 - 20 + n * 36 - Math.sin(x * 0.0035 + 2.2) * 20;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H * 0.62);
  ctx.lineTo(0, H * 0.62);
  ctx.closePath();
  const g2 = ctx.createLinearGradient(0, baseY2 - 30, 0, H * 0.6);
  g2.addColorStop(0, col(mix(hillMid, lavenderFar, 0.5)));
  g2.addColorStop(1, col(mix(hillMid, hillNear, 0.5)));
  ctx.fillStyle = g2;
  ctx.fill();

  const baseY3 = H * 0.51;
  ctx.beginPath();
  ctx.moveTo(W * 0.55, H * 0.62);
  for (let x = W * 0.55; x <= W + 10; x += 10) {
    const n = fbm(x * 0.008 + 22, 3.3, 3, 2.2, 0.55);
    const t = (x - W * 0.55) / (W * 0.45);
    const y = baseY3 - 10 + n * 30 - t * 18;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H * 0.62);
  ctx.closePath();
  ctx.fillStyle = col(mix(hillNear, lavenderDeep, 0.4));
  ctx.fill();

  const hz = ctx.createLinearGradient(0, H * 0.38, 0, H * 0.52);
  hz.addColorStop(0, col(cream, 0));
  hz.addColorStop(0.6, col(cream, 0.32));
  hz.addColorStop(1, col(cream, 0));
  ctx.fillStyle = hz;
  ctx.fillRect(0, H * 0.38, W, H * 0.14);
}

// ---------- terraces — curved overlapped hillside terraces ----------
// We build asymmetry with 3 "shoulder" bumps whose horizontality is bent by
// an x-dependent curve.  Each shoulder has its own offset & bend so the
// terracing sweeps around two-three uneven hills rather than being parallel.

// shoulder shapes: array of {cx, w, amp, bend}
const shoulders = [
  { cx: W * 0.20, w: W * 0.42, amp: 26, bend: 0.5 },
  { cx: W * 0.58, w: W * 0.55, amp: -22, bend: -0.35 },
  { cx: W * 0.90, w: W * 0.45, amp: 18, bend: 0.4 }
];

function hillOffset(x, depth) {
  // Combined shoulder influence, expanding as we come foreground.
  let off = 0;
  for (let i = 0; i < shoulders.length; i++) {
    const s = shoulders[i];
    const dx = (x - s.cx) / s.w;
    const bump = Math.exp(-dx * dx * 1.6);
    // bend: the further behind (small depth), the higher on the shoulder
    off += s.amp * bump * (0.25 + depth * 0.9);
    off += s.bend * dx * bump * (12 + depth * 40);
  }
  return off;
}

// Terrace boundary function: t depth [0,1], x horizontal
function terraceY(t, x) {
  const d = t;
  const baseY = H * 0.50 + d * H * 0.54;
  // hillside bumps into base: distant shallower, fore compresses
  const shoulder = hillOffset(x, d);
  // flowing waviness - uneven bends
  const wave =
    Math.sin(x * 0.0035 + d * 4.2) * (5 + d * 18) +
    Math.sin(x * 0.011 - d * 2.1) * (2 + d * 9);
  const nz = fbm(x * 0.009 + d * 2.3, t * 3.0 + 7, 3, 2.2, 0.55) * (8 + d * 26);
  return baseY - shoulder + wave + nz;
}

function traceCurve(t, x0, x1, steps, off) {
  ctx.beginPath();
  for (let i = 0; i <= steps; i++) {
    const x = x0 + (x1 - x0) * (i / steps);
    const y = terraceY(t, x) + off;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
}

// Field palette bands (different flooded water color per field)
const fieldPalette = [
  { top: [250, 208, 158], bot: [232, 178, 130] },  // pale amber
  { top: [250, 206, 186], bot: [232, 172, 158] },  // peach
  { top: [172, 188, 140], bot: [126, 144, 100] },  // olive green
  { top: [198, 186, 208], bot: [150, 142, 170] },  // cool lavender
  { top: [246, 220, 182], bot: [212, 184, 152] },  // warm sand
  { top: [186, 196, 164], bot: [140, 158, 118] }   // soft sage
];

const bands = 20;

function paintTerraces() {
  // base fill beneath bands for safety (also covers all)
  const baseFill = ctx.createLinearGradient(0, H * 0.42, 0, H);
  baseFill.addColorStop(0, col([228, 176, 140]));
  baseFill.addColorStop(0.35, col([216, 178, 142]));
  baseFill.addColorStop(1, col([176, 146, 118]));
  ctx.fillStyle = baseFill;
  ctx.fillRect(0, H * 0.42, W, H * 0.58);

  // choose per-band base color from palette weighted
  for (let i = 0; i < bands; i++) {
    const tt = i / bands;
    const depth = tt;
    const t0 = tt - 0.003;
    const t1 = (i + 1) / bands + 0.010;

    // band palette selection with some random mix, but grouped: more
    // amber/peach in back, more olive/lavender toward front
    let pick;
    const r = Math.random();
    if (depth < 0.35) {
      pick = r < 0.5 ? fieldPalette[0] : (r < 0.8 ? fieldPalette[1] : fieldPalette[4]);
    } else if (depth < 0.7) {
      pick = r < 0.3 ? fieldPalette[0] : (r < 0.55 ? fieldPalette[3] : (r < 0.8 ? fieldPalette[2] : fieldPalette[5]));
    } else {
      pick = r < 0.35 ? fieldPalette[2] : (r < 0.7 ? fieldPalette[3] : fieldPalette[5]);
    }

    const cTop = mix(pick.top, cream, 0.14);
    const cBot = pick.bot;
    const cMid = mix(cTop, cBot, 0.5);

    // Build band path
    const steps = 34;
    ctx.beginPath();
    for (let k = 0; k <= steps; k++) {
      const x = (k / steps) * W;
      const y = terraceY(t0, x);
      if (k === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    for (let k = steps; k >= 0; k--) {
      const x = (k / steps) * W;
      const y = terraceY(t1, x);
      ctx.lineTo(x, y);
    }
    ctx.closePath();

    // gradient fill top-down within the band region
    const yA = terraceY(t0, W * 0.5);
    const yB = terraceY(t1, W * 0.5);
    const g = ctx.createLinearGradient(0, yA - 2, 0, yB + 2);
    g.addColorStop(0, col(cTop));
    g.addColorStop(0.55, col(cMid));
    g.addColorStop(1, col(cBot));
    ctx.fillStyle = g;
    ctx.fill();

    // flooded reflection: warm pale streak across upper-mid of band
    if (Math.random() < 0.85) {
      const refl = (Math.random() < 0.55)
        ? mix(pick.top, cream, 0.55)
        : mix(waterLav, cream, 0.6);
      ctx.globalAlpha = 0.22 + depth * 0.18;
      ctx.beginPath();
      for (let k = 0; k <= steps; k++) {
        const x = (k / steps) * W;
        const yTop = terraceY(t0, x);
        const yBot = terraceY(t1, x);
        const y = yTop + (yBot - yTop) * 0.28;
        if (k === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      for (let k = steps; k >= 0; k--) {
        const x = (k / steps) * W;
        const yTop = terraceY(t0, x);
        const yBot = terraceY(t1, x);
        const y = yTop + (yBot - yTop) * 0.62;
        ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fillStyle = col(refl);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // ripple cluster: horizontal broken strokes
    const ripCount = Math.floor(30 + depth * 100);
    ctx.lineWidth = 0.6 + depth * 1.3;
    for (let k = 0; k < ripCount; k++) {
      const u = Math.random();
      const xa = u * W;
      const spanT = t0 + (t1 - t0) * (0.25 + Math.random() * 0.55);
      const ya = terraceY(spanT, xa) + (Math.random() - 0.5) * 4;
      const len = 5 + Math.random() * (12 + depth * 50);
      const alpha = 0.06 + Math.random() * 0.16;
      const c = Math.random() < 0.55
        ? mix(pick.top, cream, Math.random())
        : mix(pick.bot, waterGreenish(pick), Math.random());
      ctx.strokeStyle = col(c, alpha);
      ctx.beginPath();
      ctx.moveTo(xa, ya);
      ctx.lineTo(xa + len, ya + (Math.random() - 0.5) * 1.8);
      ctx.stroke();
    }
  }

  // Draw banks (edge ridges) with variation per band
  for (let i = 0; i < bands; i++) {
    const t = i / bands;
    const depth = t;
    const bw = 1.2 + depth * 7.0;
    const sideLit = Math.random() < 0.45;
    const steps = 30;

    // dark shadow under-edge
    traceCurve(t, 0, W, steps, 0);
    ctx.lineWidth = bw;
    ctx.strokeStyle = col(mix(bankDark, hillNear, 0.3), 0.45 + depth * 0.15);
    ctx.stroke();

    if (sideLit) {
      traceCurve(t, 0, W, steps, -bw * 0.45);
      ctx.lineWidth = bw * 0.55;
      const lit = mix(bankLit, cream, 0.30 + Math.random() * 0.28);
      ctx.strokeStyle = col(lit, 0.32 + depth * 0.28);
      ctx.stroke();
    } else {
      traceCurve(t, 0, W, steps, bw * 0.20);
      ctx.lineWidth = bw * 0.5;
      ctx.strokeStyle = col(mix(bankMid, bankDark, 0.30 + Math.random() * 0.3), 0.42);
      ctx.stroke();
    }
  }
}

function waterGreenish(p) {
  return mix(p.bot, waterOlive, 0.5);
}

// ---------- textured earth banks & rice shoots ----------
function paintBankTexture() {
  // broken texture along banks, denser in front
  const n = 3400;
  for (let i = 0; i < n; i++) {
    const depth = Math.pow(Math.random(), 0.55);
    // pick a random band edge to sit on
    const bandT = Math.floor(Math.random() * bands) / bands;
    const x = Math.random() * W;
    const y = terraceY(bandT, x) + (Math.random() - 0.5) * (2 + depth * 5);
    const size = 0.5 + depth * 1.6;
    const dark = Math.random() < 0.55;
    const c = dark
      ? mix(bankDark, [74, 54, 38], Math.random() * 0.7)
      : mix(bankLit, [216, 176, 122], Math.random() * 0.5);
    ctx.fillStyle = col(c, (0.12 + depth * 0.30) * (0.5 + Math.random() * 0.5));
    ctx.fillRect(x, y, size * (0.6 + Math.random()), size * 0.65);
  }
}

function paintRice() {
  // clustered shoots, more in mid/fore fields
  const clusters = 260;
  for (let p = 0; p < clusters; p++) {
    const depth = 0.18 + Math.pow(Math.random(), 0.7) * 0.82;
    const bandT = Math.floor(Math.random() * bands) / bands;
    const xc = Math.random() * W;
    // keep them near band interiors (above bank)
    const yc = terraceY(bandT, xc) + 2;
    if (Math.random() < 0.35 && depth < 0.5) continue;
    const count = 4 + Math.floor(Math.random() * (4 + depth * 8));
    const clusterCol = Math.random() < 0.5 ? riceGreen : riceDark;
    for (let k = 0; k < count; k++) {
      const dx = (Math.random() - 0.5) * (8 + depth * 34);
      const x = xc + dx;
      const y = yc - Math.random() * 1.5;
      const h = (2 + depth * 8) * (0.6 + Math.random() * 0.9);
      const lean = (Math.random() - 0.5) * 1.4;
      const c = mix(clusterCol,
                    Math.random() < 0.5 ? [146, 164, 100] : [62, 80, 46],
                    Math.random() * 0.6);
      ctx.strokeStyle = col(c, 0.55 + Math.random() * 0.35);
      ctx.lineWidth = 0.65 + depth * 0.9;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + lean * 1.2, y - h * 0.5, x + lean * 2, y - h);
      ctx.stroke();
    }
  }
}

// ---------- tiny huts on a mid-terrace ----------
function paintRoofs() {
  // cluster on a mid-left shoulder ridge
  const baseX = W * 0.20;
  const baseY = terraceY(0.42, baseX) - 2;
  const nHuts = 5;
  for (let i = 0; i < nHuts; i++) {
    const x = baseX + i * 22 + (Math.random() - 0.5) * 6;
    const y = baseY - Math.random() * 6 + i * 3;
    const w = 14 + Math.random() * 6;
    const h = 6 + Math.random() * 3;
    // shadow
    ctx.fillStyle = col([70, 50, 40], 0.20);
    ctx.beginPath();
    ctx.ellipse(x, y + h * 0.9, w * 0.55, 2, 0, 0, Math.PI * 2);
    ctx.fill();
    // wall
    ctx.fillStyle = col(mix([128, 98, 80], [96, 74, 60], Math.random()), 0.92);
    ctx.fillRect(x - w * 0.4, y, w * 0.8, h * 0.9);
    // roof
    ctx.fillStyle = col(mix([122, 78, 60], [86, 56, 44], Math.random()), 0.95);
    ctx.beginPath();
    ctx.moveTo(x - w * 0.62, y);
    ctx.lineTo(x, y - h);
    ctx.lineTo(x + w * 0.62, y);
    ctx.closePath();
    ctx.fill();
    // warm window glow
    if (Math.random() < 0.75) {
      ctx.fillStyle = col([250, 206, 132], 0.85);
      ctx.fillRect(x - 1.2, y + h * 0.35, 2, 1.8);
    }
    // side ladder hint
    if (Math.random() < 0.5) {
      ctx.strokeStyle = col([80, 56, 42], 0.7);
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(x + w * 0.45, y + h * 0.9);
      ctx.lineTo(x + w * 0.5, y - 1);
      ctx.stroke();
    }
  }
  // small second cluster right
  const bx2 = W * 0.72;
  const by2 = terraceY(0.55, bx2) - 1;
  for (let i = 0; i < 3; i++) {
    const x = bx2 + i * 20 + (Math.random() - 0.5) * 5;
    const y = by2 - Math.random() * 5 + i * 2;
    const w = 12 + Math.random() * 5;
    const h = 5 + Math.random() * 3;
    ctx.fillStyle = col([90, 68, 54], 0.9);
    ctx.fillRect(x - w * 0.4, y, w * 0.8, h * 0.85);
    ctx.fillStyle = col(mix([116, 74, 56], [80, 52, 40], Math.random()), 0.95);
    ctx.beginPath();
    ctx.moveTo(x - w * 0.6, y);
    ctx.lineTo(x, y - h);
    ctx.lineTo(x + w * 0.6, y);
    ctx.closePath();
    ctx.fill();
    if (Math.random() < 0.6) {
      ctx.fillStyle = col([248, 200, 130], 0.8);
      ctx.fillRect(x - 1, y + h * 0.35, 1.8, 1.5);
    }
  }
}

// ---------- slender trees ----------
function paintTrees() {
  const spots = [
    [W * 0.05, 0.20], [W * 0.09, 0.22], [W * 0.30, 0.16],
    [W * 0.44, 0.18], [W * 0.62, 0.12], [W * 0.71, 0.15],
    [W * 0.86, 0.10], [W * 0.92, 0.16], [W * 0.52, 0.24],
    [W * 0.24, 0.28], [W * 0.78, 0.22]
  ];
  for (const [x, t] of spots) {
    const y = terraceY(t, x) - 2;
    const h = 14 + Math.random() * 20 + t * 20;
    const w = 2 + Math.random() * 2.2;
    // shadow at base
    ctx.fillStyle = col([60, 44, 34], 0.15);
    ctx.beginPath();
    ctx.ellipse(x, y + 1, 4 + Math.random() * 3, 1.2, 0, 0, Math.PI * 2);
    ctx.fill();
    // trunk
    ctx.strokeStyle = col(mix(bankDark, [56, 40, 30], Math.random()), 0.92);
    ctx.lineWidth = w * (0.7 + Math.random() * 0.5);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + (Math.random() - 0.5) * 3, y - h * 0.6, x + (Math.random() - 0.5) * 4, y - h);
    ctx.stroke();
    // branches & foliage hints
    for (let k = 0; k < 5; k++) {
      const by = y - h * (0.35 + k * 0.14);
      const bx = x + (Math.random() - 0.5) * 2;
      const bh = h * (0.15 + Math.random() * 0.20);
      const lean = (Math.random() - 0.5) * 6;
      ctx.strokeStyle = col(mix(bankDark, [48, 38, 28], Math.random()), 0.7);
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(bx + lean, by - bh);
      ctx.stroke();
      // small foliage dabs
      if (Math.random() < 0.5) {
        ctx.fillStyle = col(mix([80, 100, 60], [56, 76, 44], Math.random()), 0.55);
        ctx.beginPath();
        ctx.ellipse(bx + lean, by - bh, 2 + Math.random() * 2, 1.5 + Math.random(), 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
}

// ---------- foreground scrub / edge ----------
function paintForeground() {
  // foreground lower banks get bigger, darker, denser
  const y0 = H * 0.965;
  const g = ctx.createLinearGradient(0, y0 - 30, 0, H);
  g.addColorStop(0, col([150, 122, 92], 0));
  g.addColorStop(1, col([120, 96, 72], 0.55));
  ctx.fillStyle = g;
  ctx.fillRect(0, y0 - 30, W, H - (y0 - 30));
  // scattered dark earth bumps
  for (let i = 0; i < 300; i++) {
    const x = Math.random() * W;
    const y = rnd(H * 0.94, H);
    const s = 1 + Math.random() * 3;
    ctx.fillStyle = col(mix([90, 68, 50], [140, 110, 82], Math.random()), 0.35);
    ctx.beginPath();
    ctx.ellipse(x, y, s, s * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // a few tall fore grasses
  for (let i = 0; i < 60; i++) {
    const x = Math.random() * W;
    const y = rnd(H * 0.95, H);
    const h = 5 + Math.random() * 14;
    const lean = (Math.random() - 0.5) * 4;
    ctx.strokeStyle = col(mix(riceDark, [50, 60, 40], Math.random()), 0.6);
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + lean * 0.5, y - h * 0.5, x + lean, y - h);
    ctx.stroke();
  }
}

// ---------- finish ----------
function finish() {
  // warm side glow from right
  const lg = ctx.createLinearGradient(W, H * 0.55, W * 0.3, H);
  lg.addColorStop(0, col([255, 210, 150], 0.15));
  lg.addColorStop(0.5, col([250, 200, 160], 0.05));
  lg.addColorStop(1, col([200, 180, 200], 0));
  ctx.fillStyle = lg;
  ctx.fillRect(0, H * 0.35, W, H * 0.65);

  // subtle vignette
  const vg = ctx.createRadialGradient(W / 2, H * 0.55, H * 0.30, W / 2, H * 0.55, H * 0.95);
  vg.addColorStop(0, col([0, 0, 0], 0));
  vg.addColorStop(1, col([40, 30, 50], 0.20));
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

